type TaxRec struct {
	TrId     string
	TrIncome decimal.Decimal
}

var WsEofFlag string
var WsTax decimal.Decimal
var WsNet decimal.Decimal
var WsTotalTax decimal.Decimal
var WsCount int64
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var TaxRecVar TaxRec

func storeDecimal(v decimal.Decimal, intDigits int, scale int32, rounded bool) decimal.Decimal {
	if rounded {
		v = v.Round(scale)
	} else {
		v = v.Truncate(scale)
	}
	// high-order truncation: keep low-order digits that fit
	// total digits = intDigits + scale
	total := int64(intDigits) + int64(scale)
	if total <= 0 {
		return v
	}
	// compute modulus = 10^total
	mod := decimal.NewFromInt(1)
	ten := decimal.NewFromInt(10)
	for i := int64(0); i < total; i++ {
		mod = mod.Mul(ten)
	}
	// scaled integer
	shifted := v.Shift(scale) // v *10^scale
	// For negative, handle sign separately keeping magnitude modulo
	sign := int32(1)
	if shifted.IsNegative() {
		sign = -1
		shifted = shifted.Neg()
	}
	// truncate to integer (should already be integer after shift if scale correct)
	shifted = shifted.Truncate(0)
	// modulo
	// shifted = shifted % mod
	// decimal.Mod not reliable for large, use Int part via string? Use DivMod via decimal? simple loop using Mod method
	shifted = shifted.Mod(mod)
	if sign == -1 {
		shifted = shifted.Neg()
	}
	result := shifted.Shift(-scale)
	// ensure scale exactly scale (add trailing zeros)
	result = result.Truncate(scale)
	return result
}

func formatNumericEdited(val decimal.Decimal, pic string) string {
	// parse pic
	// count fractional digits after '.'
	dotIdx := strings.Index(pic, ".")
	fracDigits := 0
	intPic := pic
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPart := pic[dotIdx+1:]
		for _, ch := range fracPart {
			if ch == '9' || ch == 'Z' {
				fracDigits++
			}
		}
	}
	// digit placeholders in int part
	intDigitsPic := 0
	for _, ch := range intPic {
		if ch == '9' || ch == 'Z' {
			intDigitsPic++
		}
	}
	// absolute value
	neg := val.IsNegative()
	absVal := val
	if neg {
		absVal = absVal.Neg()
	}
	// round/truncate to fracDigits? The MOVE already truncates, but ensure
	absVal = absVal.Truncate(int32(fracDigits))

	// integer part modulo 10^intDigitsPic if overflow
	// get integer part
	intPart := absVal.Truncate(0)
	fracPartVal := absVal.Sub(intPart)
	// handle overflow dropping high digits using modulo
	if intDigitsPic > 0 {
		modInt := decimal.NewFromInt(1)
		ten := decimal.NewFromInt(10)
		for i := 0; i < intDigitsPic; i++ {
			modInt = modInt.Mul(ten)
		}
		// intPart is normalized, need modulo
		// intPart may be large, use Mod
		intPartMod := intPart.Mod(modInt)
		// Mod for positive yields remainder
		intPart = intPartMod
	}
	// build integer digits string zero-padded to intDigitsPic
	intStr := intPart.StringFixed(0) // no decimals
	// StringFixed may produce like "0"
	// pad
	if len(intStr) < intDigitsPic {
		intStr = strings.Repeat("0", intDigitsPic-len(intStr)) + intStr
	} else if len(intStr) > intDigitsPic {
		// if still longer (should not), keep rightmost
		intStr = intStr[len(intStr)-intDigitsPic:]
	}
	// fractional string
	fracStr := ""
	if fracDigits > 0 {
		// get fractional scaled
		// fracPartVal *10^fracDigits
		scaledFrac := fracPartVal.Shift(int32(fracDigits)).Truncate(0).Abs()
		s := scaledFrac.StringFixed(0)
		if len(s) < fracDigits {
			s = strings.Repeat("0", fracDigits-len(s)) + s
		}
		fracStr = s
	}

	// Build integer edited section char by char
	// intPic length = len(intPic)
	intPicChars := []rune(intPic)
	resInt := make([]rune, len(intPicChars))
	digitIdx := 0
	for i, ch := range intPicChars {
		if ch == '9' || ch == 'Z' {
			resInt[i] = rune(intStr[digitIdx])
			digitIdx++
		} else {
			// comma etc placeholder, will set later
			resInt[i] = ch // comma placeholder
		}
	}
	// Z suppression
	stillSuppressing := true
	// iterate over digit positions in order
	for i, ch := range intPicChars {
		if ch == '9' || ch == 'Z' {
			d := resInt[i] // digit char
			if stillSuppressing {
				if d != '0' {
					stillSuppressing = false
					// keep digit
				} else {
					if ch == 'Z' {
						// replace with space
						resInt[i] = ' '
					} else {
						// '9' zero must show, end suppression
						stillSuppressing = false
						// keep '0'
					}
				}
			}
		} else {
			// comma or other literal
			if ch == ',' {
				if stillSuppressing {
					resInt[i] = ' '
				} else {
					resInt[i] = ','
				}
			} else {
				resInt[i] = ch
			}
		}
	}
	combined := string(resInt)
	if dotIdx >= 0 {
		combined = combined + "." + fracStr
	}
	// handle negative: put '-' at leftmost space if needed
	if neg {
		// find first space from left to replace with '-'
		// COBOL would show minus, place at leftmost suppressed position or before
		found := false
		runes := []rune(combined)
		for i, r := range runes {
			if r == ' ' {
				// look ahead if there is digit after? simple replace leftmost non-space? For this task not needed
				// We'll replace the last space before first digit
				// Find last space before first digit
				continue
			}
			_ = i
			_ = r
		}
		// simple: replace first space with '-' or prepend
		// We'll just prepend '-' and drop one leading char if overflow
		// But tax never negative, skip
		_ = found
	}
	// ensure length equals pic length
	if len(combined) < len(pic) {
		combined = strings.Repeat(" ", len(pic)-len(combined)) + combined
	} else if len(combined) > len(pic) {
		combined = combined[len(combined)-len(pic):]
	}
	return combined
}

func displayLine(parts ...string) {
	var sb strings.Builder
	for _, p := range parts {
		sb.WriteString(p)
	}
	sb.WriteString("\n")
	os.Stdout.WriteString(sb.String())
}

func readPara(reader *bufio.Reader, eof *bool) {
	// Actually we read via slice iterator; this function is called via PERFORM logic handling line index externally
	// placeholder not used
	_ = reader
	_ = eof
}

// file reading helpers
var inputLines []string
var inputIdx int

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseTaxRec(line string) TaxRec {
	// pad to 13
	if len(line) < 13 {
		line = line + strings.Repeat(" ", 13-len(line))
	} else if len(line) > 13 {
		line = line[:13]
	}
	trIdRaw := line[0:5]
	trIncomeRaw := line[5:13]
	// trId is X(5) exactly
	trId := trIdRaw // keep spaces
	// parse income digits
	digits := strings.TrimSpace(trIncomeRaw)
	if digits == "" {
		digits = "0"
	}
	// digits may contain spaces? Keep only digits
	// According spec numeric fields contain digits only, but handle
	filtered := ""
	for _, c := range digits {
		if c >= '0' && c <= '9' {
			filtered += string(c)
		}
	}
	if filtered == "" {
		filtered = "0"
	}
	// parse as integer and shift -2
	dInt, _ := decimal.NewFromString(filtered)
	// alternative: use New with exponent
	// dInt is integer value of digits, e.g., "000100000" -> 100000
	// then decimal with scale 2 => New(n, -2)
	// NewFromString gives n, we need shift
	val := decimal.NewFromBigInt(dInt.BigInt(), -2)
	// Ensure exactly scale 2 truncate? Input already digits only, so exact
	return TaxRec{TrId: trId, TrIncome: val}
}

func MAIN_PARA() {
	// OPEN INPUT TAX-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty
		inputLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		// Don't use default split that strips newline only; need to keep lines as is without newline.
		// Scanner returns line without newline, which is record. That's fine.
		for scanner.Scan() {
			line := scanner.Text()
			// Scanner strips trailing \r; keep as is. Need to preserve spaces? Scanner strips final newline but keeps other spaces; trailing spaces are trimmed by Scanner? Actually Scanner returns line without newline, but trailing spaces are kept? bufio.Scanner trims \r\n but keeps other spaces. However Go's Scanner may strip final \r. That's okay.
			// But note: input is LINE SEQUENTIAL, each line corresponds to record; padding is applied later, so trailing spaces not significant for numeric but for X field they would be spaces. If line is shorter, we pad. So losing trailing spaces is okay.
			inputLines = append(inputLines, line)
		}
		f.Close()
	}
	// PERFORM READ-PARA
	READ_PARA()
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	// CLOSE done
	WsTotalEd = formatNumericEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	displayLine("TAXPAYERS: ", fmt.Sprintf("%03d", WsCount), " TOTAL TAX: ", WsTotalEd)
}

func READ_PARA() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	TaxRecVar = parseTaxRec(line)
	WsEofFlag = "N"
}

func PROCESS_PARA() {
	tenPct := decimal.NewFromInt(10).Shift(-2)   // 0.10
	twentyPct := decimal.NewFromInt(20).Shift(-2) // 0.20
	thirtyPct := decimal.NewFromInt(30).Shift(-2) // 0.30
	limit1 := decimal.NewFromInt(10000)
	limit2 := decimal.NewFromInt(40000)
	const1000 := decimal.NewFromInt(1000)
	const7000 := decimal.NewFromInt(7000)

	if TaxRecVar.TrIncome.Cmp(limit1) <= 0 {
		comp := TaxRecVar.TrIncome.Mul(tenPct)
		WsTax = storeDecimal(comp, 7, 2, true)
	} else {
		if TaxRecVar.TrIncome.Cmp(limit2) <= 0 {
			diff := TaxRecVar.TrIncome.Sub(limit1)
			comp := const1000.Add(diff.Mul(twentyPct))
			WsTax = storeDecimal(comp, 7, 2, true)
		} else {
			diff := TaxRecVar.TrIncome.Sub(limit2)
			comp := const7000.Add(diff.Mul(thirtyPct))
			WsTax = storeDecimal(comp, 7, 2, true)
		}
	}
	// COMPUTE WS-NET = TR-INCOME - WS-TAX
	compNet := TaxRecVar.TrIncome.Sub(WsTax)
	WsNet = storeDecimal(compNet, 7, 2, false)
	// ADD WS-TAX TO WS-TOTAL-TAX
	WsTotalTax = storeDecimal(WsTotalTax.Add(WsTax), 9, 2, false)
	// ADD 1 TO WS-COUNT ( truncation to 3 digits )
	WsCount = (WsCount + 1) % 1000
	// MOVE to edited
	WsIncEd = formatNumericEdited(TaxRecVar.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatNumericEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatNumericEdited(WsNet, "ZZZ,ZZ9.99")
	displayLine(TaxRecVar.TrId, " ", WsIncEd, " ", WsTaxEd, " ", WsNetEd)
	READ_PARA()
}

func main() {
	WsEofFlag = "N"
	WsTax = decimal.NewFromInt(0)
	WsNet = decimal.NewFromInt(0)
	WsTotalTax = decimal.NewFromInt(0)
	WsCount = 0
	MAIN_PARA()
}
